export function buscarNbsLancamento(codEmpresa: number, lancamento: number): NbsRow[] {
  return NBS_MOCK
    .filter(r => r.cod_empresa === codEmpresa && r.lancamento === lancamento)
    .sort((a, b) => a.cod_contabil.localeCompare(b.cod_contabil) || a.cod_centro_custo - b.cod_centro_custo);
}
